-- =============================================================================
-- Toojibee: full MySQL schema SNAPSHOT (generated, do not edit by hand)
-- =============================================================================
-- This is migrations/001..NNN concatenated, for reading the whole schema in
-- one place or creating a fresh database in one go. The migrations folder is
-- the source of truth: change the schema by adding a new migration, then
-- regenerate this file (see database/README.md).

-- =============================================================================
-- 001 — initial schema (MySQL 8.0.16+)
-- =============================================================================
-- Mirrors the data shape the /demo/ app already uses (state.tasks,
-- state.habits, state.events, state.profile, state.settings and the
-- connections list), so the API can hand the client the same objects
-- it keeps in memory today.
--
-- Design choices:
--
-- 1. Ids are CHAR(36) UUIDs generated by the client or the API, never
--    AUTO_INCREMENT: the app creates items offline-first and upserts them
--    by id, and sequential ids would leak row counts.
--
-- 2. Subtasks, photos, recurrence, notification and habit check-in dates
--    are JSON columns, not child tables. The UI always reads and writes
--    each of them as one whole value together with its parent row, and
--    nothing queries them on their own ("which tasks have a subtask
--    called X"). A child table would only add joins and multi-row writes.
--
-- 3. utf8mb4 everywhere: titles are Persian and may contain emoji.
--    utf8mb4_0900_ai_ci is case-insensitive, so the email and username
--    UNIQUE keys already reject "A@x.com" next to "a@x.com".
--
-- 4. CHECK constraints are enforced from MySQL 8.0.16. Older servers parse
--    and silently ignore them, which is why the README requires 8.0.16+.
-- =============================================================================

SET NAMES utf8mb4;

-- ── users & auth ─────────────────────────────────────────────────────────
CREATE TABLE users (
  id            CHAR(36)     NOT NULL,
  email         VARCHAR(255) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY users_email_uq (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per issued token. Only a SHA-256 of the token is stored, so a
-- leaked database dump cannot be replayed as live sessions. Deleting the
-- row is what makes logout and revocation work.
CREATE TABLE sessions (
  id          CHAR(36)     NOT NULL,
  user_id     CHAR(36)     NOT NULL,
  token_hash  CHAR(64)     NOT NULL,
  user_agent  VARCHAR(255) NULL,
  expires_at  DATETIME     NOT NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY sessions_token_uq (token_hash),
  KEY sessions_user_idx (user_id),
  CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE profiles (
  user_id     CHAR(36)     NOT NULL,
  first_name  VARCHAR(100) NOT NULL DEFAULT '',
  last_name   VARCHAR(100) NOT NULL DEFAULT '',
  username    VARCHAR(50)  NULL,            -- NULL until the user picks one
  phone       VARCHAR(30)  NOT NULL DEFAULT '',
  gender      ENUM('male', 'female') NULL,
  dob         DATE         NULL,
  photo_url   MEDIUMTEXT   NULL,            -- NULL = show initials
  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  UNIQUE KEY profiles_username_uq (username),
  KEY profiles_phone_idx (phone),
  CONSTRAINT profiles_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_settings (
  user_id               CHAR(36) NOT NULL,
  language              ENUM('fa', 'en') NOT NULL DEFAULT 'fa',
  calendar_system       ENUM('jalali', 'gregorian', 'hijri') NOT NULL DEFAULT 'jalali',
  week_start_day        ENUM('saturday', 'sunday', 'monday') NOT NULL DEFAULT 'saturday',
  notifications         BOOLEAN  NOT NULL DEFAULT TRUE,
  show_add_menu_labels  BOOLEAN  NOT NULL DEFAULT TRUE,
  theme                 ENUM('dark', 'light') NOT NULL DEFAULT 'dark',
  updated_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  CONSTRAINT user_settings_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ── tasks ─────────────────────────────────────────────────────────────────
-- subtasks:     [{ "id": "...", "text": "...", "done": false }]
-- photos:       ["data:image/webp;base64,..." | "https://..."]
-- recurrence:   { "mode": null | "interval" | "weekdays", "interval": 1, "weekdays": [0-6] }
-- notification: { "type": null | "time" | "repeating", "time": "18:00", "repeatHours": 2, "text": "" }
CREATE TABLE tasks (
  id            CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NOT NULL,
  title         VARCHAR(500) NOT NULL,
  category      VARCHAR(100) NOT NULL DEFAULT '',
  description   TEXT         NULL,
  pinned        BOOLEAN      NOT NULL DEFAULT FALSE,
  done          BOOLEAN      NOT NULL DEFAULT FALSE,
  skipped       BOOLEAN      NOT NULL DEFAULT FALSE,   -- explicit "not done" (red X)
  time_mode     ENUM('single', 'range') NOT NULL DEFAULT 'single',
  date          DATE         NOT NULL,                 -- start date
  end_date      DATE         NULL,                     -- deadline, range only
  subtasks      JSON         NOT NULL DEFAULT (JSON_ARRAY()),
  photos        JSON         NOT NULL DEFAULT (JSON_ARRAY()),
  recurrence    JSON         NULL,
  notification  JSON         NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY tasks_user_date_idx (user_id, date),
  CONSTRAINT tasks_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT tasks_range_ck CHECK (time_mode = 'single' OR end_date IS NOT NULL),
  CONSTRAINT tasks_order_ck CHECK (end_date IS NULL OR end_date >= date),
  CONSTRAINT tasks_not_both_ck CHECK (NOT (done AND skipped))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ── habits ────────────────────────────────────────────────────────────────
-- completed_dates / skipped_dates: ["2026-10-14", ...]
CREATE TABLE habits (
  id               CHAR(36)     NOT NULL,
  user_id          CHAR(36)     NOT NULL,
  title            VARCHAR(500) NOT NULL,
  start_date       DATE         NOT NULL,
  recurrence       JSON         NULL,
  notification     JSON         NULL,
  completed_dates  JSON         NOT NULL DEFAULT (JSON_ARRAY()),
  skipped_dates    JSON         NOT NULL DEFAULT (JSON_ARRAY()),
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY habits_user_idx (user_id),
  CONSTRAINT habits_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ── events ────────────────────────────────────────────────────────────────
CREATE TABLE events (
  id            CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NOT NULL,
  title         VARCHAR(500) NOT NULL,
  time_mode     ENUM('single', 'range') NOT NULL DEFAULT 'single',
  date          DATE         NOT NULL,
  end_date      DATE         NULL,
  recurrence    JSON         NULL,
  notification  JSON         NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY events_user_date_idx (user_id, date),
  CONSTRAINT events_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT events_range_ck CHECK (time_mode = 'single' OR end_date IS NOT NULL),
  CONSTRAINT events_order_ck CHECK (end_date IS NULL OR end_date >= date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ── connections (friends) ─────────────────────────────────────────────────
-- One row per pair of users, stored with user_a < user_b so a pair can
-- never exist twice in opposite directions. requested_by says who sent the
-- request (or who blocked); the API turns that into the client's
-- pending-outgoing / pending-incoming / blocked-by-them vocabulary.
CREATE TABLE connections (
  user_a        CHAR(36) NOT NULL,
  user_b        CHAR(36) NOT NULL,
  status        ENUM('pending', 'accepted', 'blocked') NOT NULL,
  requested_by  CHAR(36) NOT NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_a, user_b),
  KEY connections_user_b_idx (user_b),
  CONSTRAINT connections_a_fk FOREIGN KEY (user_a) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT connections_b_fk FOREIGN KEY (user_b) REFERENCES users (id) ON DELETE CASCADE
  -- "user_a < user_b" and "requested_by is one of the pair" are enforced in
  -- backend/src/routes/connections.js: MySQL rejects CHECK constraints on
  -- columns that have ON DELETE CASCADE foreign keys (error 3823).
)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
